import { _decorator, Component, director, Node } from 'cc';
import { Bus } from '../Engine/Bus';
import { World } from '../Engine/World';
import { ViewRegistry } from '../Engine/ViewRegistry';
import { FixedTick } from '../Engine/Tick';
import { EntityPool } from '../Core/Pool/EntityPool';
import { GameData } from '../Core/Data/GameData';
import { HallInputHandler } from './HallInputHandler';


import { EconomySystem } from './System/EconomySystem';
import { BuildSystem } from './System/BuildSystem';
import { ProduceSystem } from './System/ProduceSystem';
import { MonthClockSystem } from './System/MonthClockSystem';
import { UpgradeSystem } from './System/UpgradeSystem';
import { SynergySystem } from './System/SynergySystem';
import { QuestSystem } from './System/QuestSystem';
import { SettlementSystem } from './System/SettlementSystem';


import { BuildingView } from './View/BuildingView';
import { GridView } from './View/GridView';
import { HallViewModel } from './ViewModel/HallViewModel';
import { HallEvents } from './HallEvents';
import { BUILDING_CONFIG } from './Config/BuildingConfig';
import { BuildingEntity } from './Entity/BuildingEntity';

import { GridMap } from './Data/GridMap';
import { GhostSystem } from './System/GhostSystem';
import { GridSyncSystem } from './System/GridSyncSystem';
import { gridToLocal } from './Config/GridConfig';
import { ViewPool } from '../Engine/ViewPool';
import { GhostEntity } from './Entity/GhostEntity';
import { GhostView } from './View/GhostView';
import { WorldViewController } from './View/WorldViewController';

const { ccclass ,property} = _decorator;

@ccclass('HallScene')
export class HallScene extends Component {


    @property(Node)
    worldRoot: Node = null;
    @property(Node)
    gridLayer: Node = null;
    @property(Node)
    entityLayer: Node = null;
    @property(Node)
    inputCatcher: Node = null;


    private _bus: Bus = null!;
    private _world: World = null!;
    private _views: ViewRegistry = null!;
    private _viewModel: HallViewModel = null!;
    
    private _worldViewController: WorldViewController = null!;
    private _tick: FixedTick = null!;
    private _gridView: GridView = null!;

    protected start(): void {
        GameData.init();
        this._createBus();
        this._createMap();
        this._rebuildViewModel();   
        this._setupInput();   
        this._registerSceneListeners(); 
        this._launchWorld();

     
    }

    onDestroy(): void {
        this._unregisterSceneListeners();
        this._tick?.stop();
        this._viewModel?.onDestroy();
        this._world?.destroy();
    }

    private _createBus(): void {
        this._bus = new Bus();
    }

    private _createMap(){

        this._gridView = this.gridLayer.getComponent(GridView)!;

        if (this._gridView) {
            this._gridView.createMap(); 
        }
    }

    private _rebuildViewModel(): void {
        this._viewModel?.onDestroy();
        this._viewModel = new HallViewModel(this._bus)
    }

    private _setupInput(): void {
        this.inputCatcher.getComponent(HallInputHandler).setup(this._bus, this.worldRoot);
        this._worldViewController = this.node.addComponent(WorldViewController);
        this._worldViewController.setup(this._bus, this.worldRoot);
    }

    private _registerSceneListeners(): void {

    }
    
    private _unregisterSceneListeners(): void {

    }

    private _launchWorld(): void {
        this._buildWorld();
        this._startTick();
    }

    private _buildWorld(){
        this._views = new ViewRegistry(this.entityLayer,new ViewPool(256));
        const pool = new EntityPool(512);
        this._world = new World(this._bus, this._views,pool);
        this._registerViewFactories();
        this._installSystems();
    }

    private _registerViewFactories(): void {

        this._views.registerFactory('building', (e) => {
            const node = new Node('Building_${e.id}');
            return node.addComponent(BuildingView);
        });

        this._views.registerFactory('ghost',(e) => {
            const node = new Node('ghost_${e.id}');
            return node.addComponent(GhostView);
        });
    }
   

    private _installSystems(): void {

        const gridMap = new GridMap();

        // 2. 装配系统
        // GhostSystem 依赖 gridMap 查空位
        this._world.addSystem(new GhostSystem(gridMap)); 

        // BuildSystem 不再依赖 gridMap，专心造实体
        this._world.addSystem(new BuildSystem());       

        // GridSyncSystem 依赖 gridMap，专心写数据
        this._world.addSystem(new GridSyncSystem(gridMap)); 
        this._world.addSystem(new EconomySystem());
        this._world.addSystem(new ProduceSystem());
        this._world.addSystem(new MonthClockSystem());

        this._world.addSystem(new UpgradeSystem());
        this._world.addSystem(new SynergySystem());
        this._world.addSystem(new QuestSystem());
        this._world.addSystem(new SettlementSystem());
    }

    // =========================================================
    //  Tick 启停
    // =========================================================
    private _startTick(): void {
        if (!this._tick) {
            this._tick = this.node.addComponent(FixedTick);
        }
        this._tick.setup(this._world, this._views);
        this._tick.begin();
    }

    private _stopTick(): void {
        this._tick?.stop();
    }




}